  const makeCode=()=>{const abc='ABCDEFGHJKMNPQRSTUVWXYZ23456789';let c='MC-';const u=new Uint32Array(6);(crypto?.getRandomValues?crypto.getRandomValues(u):[...Array(6)].map(()=>Math.random()*2**32)).forEach(v=>c+=abc[v%32]);return c}
  let _syncTimer=null;
