  function exportData(){let blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mon-carnet-marianne.json';a.click();URL.revokeObjectURL(a.href)}

  document.addEventListener('click',e=>{let el=e.target.closest?.('[data-view],[data-action]');if(!el||el.disabled)return;let v=el.dataset.view,a=el.dataset.action;if(v){if(v==='day')return render('day');return render(v)}if(a==='open-day'){if(unlocked(el.dataset.day)){patch({day:Number(el.dataset.day)});render('day')}return}if(a==='finish'){let n=Number(el.dataset.day);patch({completed:[...new Set([...state.completed,n])].sort((x,y)=>x-y),day:Math.min(14,n+1)});toast('Journée enregistrée dans ton carnet.');render('day');return}if(a==='redo-profile'){patch({profileComplete:false,view:'home'});render('home');return}if(a==='save-name'){patch({name:document.querySelector('#name')?.value.trim().slice(0,24)||''});render('home');return}if(a==='answer'){let d=getDay(el.dataset.day);patch({quiz:{...state.quiz,[d.id]:Number(el.dataset.answer)}});render('day');return}if(a==='scenario-answer'){let d=Number(el.dataset.day);patch({scenarios:{...(state.scenarios||{}),[d]:Number(el.dataset.answer)}});render('day');return}if(a==='save-question'){let id='d'+el.dataset.day;patch({saved:state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id]});render('day');toast(state.saved.includes(id)?'Repère retiré.':'Repère ajouté au carnet.');return}if(a==='speak'){let d=getDay(el.dataset.day);patch({listened:[...new Set([...state.listened,d.id])]});speak(d.listen);return}if(a==='speak-text'){speak(el.dataset.text);return}if(a==='pause'){if(speechSynthesis.paused)speechSynthesis.resume();else speechSynthesis.pause();return}if(a==='stop'){speechSynthesis.cancel();return}if(a==='mode'){practice={kind:el.dataset.mode};if(el.dataset.mode==='qcm'||el.dataset.mode==='situations')practice.q=shuffle(el.dataset.mode==='situations'?ALL_S:ALL_Q).map(shufOpts)[0];if(el.dataset.mode==='cards')practice.idx=0;if(el.dataset.mode==='true'){practice.idx=0;practice._tfOk=undefined;}if(el.dataset.mode==='oral')practice.idx=0;return render('practice')}if(a==='back-practice'){practice=null;return render('practice')}if(a==='practice-answer'){practice.selected=Number(el.dataset.answer);if(practice.kind==='chrono'&&practice.selected===practice.q.ok)practice.score=(practice.score||0)+1;markAnswer(practice.q?.theme,practice.selected===practice.q?.ok);return render('practice')}if(a==='practice-next'){practice.q=shufOpts(shuffle(practice.kind==='situations'?ALL_S:ALL_Q)[0]);practice.selected=null;return render('practice')}if(a==='flip'){practice.flipped=!practice.flipped;return render('practice')}if(a==='card-next'){practice.idx=(practice.idx||0)+1;practice.flipped=false;markPractice();return render('practice')}if(a==='tf-answer'){practice.selected=el.dataset.value;const _tfThemes=['Principes et valeurs','Principes et valeurs','Institutions','Vie quotidienne','Principes et valeurs','Institutions'];markAnswer(_tfThemes[(practice.idx||0)%6],el.dataset.value===String(practice._tfOk));return render('practice')}if(a==='tf-next'){practice.idx=(practice.idx||0)+1;practice.selected=null;return render('practice')}if(a==='oral-next'){practice.idx=(practice.idx||0)+1;practice.note=document.querySelector('#oral-note')?.value||'';markPractice();return render('practice')}if(a==='start-chrono'){practice={kind:'chrono',started:true,left:60,score:0,q:shuffle(ALL_Q).map(shufOpts)[0],selected:null};practice.timer=setInterval(()=>{if(!practice||practice.kind!=='chrono')return;practice.left--;if(practice.left<=0)clearInterval(practice.timer);render('practice')},1000);return render('practice')}if(a==='stop-chrono'){clearInterval(practice?.timer);practice=null;return render('practice')}if(a==='start-exam'){return startExam()}if(a==='exam-answer'){practice.answers[practice.idx]=Number(el.dataset.answer);const _q=practice.qs?.[practice.idx];markAnswer(_q?.theme,practice.answers[practice.idx]===_q?.ok);return render('practice')}if(a==='exam-next'){if(practice.idx===39)return finishExam();practice.idx++;return render('practice')}if(a==='play-video'){const v=(typeof VIDEO_CATALOG!=='undefined'?VIDEO_CATALOG:[]).find(x=>x.slug===el.dataset.slug);if(!v)return;if(!(state.videosWatched||[]).includes(v.slug))patch({videosWatched:[...(state.videosWatched||[]),v.slug]});document.querySelector('.vid-modal')?.remove();const o=document.createElement('div');o.className='vid-modal';o.setAttribute('role','dialog');o.setAttribute('aria-label',v.title);o.innerHTML=`<div class="vid-box"><div class="vid-head"><h3>${v.title}</h3><button data-action="close-video" aria-label="Fermer">✕</button></div><video controls playsinline poster="${v.poster}" src="${v.mp4}"><track kind="subtitles" src="${v.vtt}" label="Français" srclang="fr" default></video><p class="vid-meta">${v.count} questions · ~${Math.max(1,Math.round(v.duration/60))} min · ${v.themes.join(' + ')}</p></div>`;document.body.appendChild(o);const vd=o.querySelector('video');o.addEventListener('click',e2=>{if(e2.target===o){vd.pause();o.remove();}});vd.addEventListener('keydown',e2=>{if(e2.key==='Escape'){vd.pause();o.remove();}});try{const pr=vd.play&&vd.play();pr&&pr.catch(()=>{})}catch(_){}return}
if(a==='close-video'){const o=document.querySelector('.vid-modal');if(o){o.querySelector('video')?.pause();o.remove();}return}
if(a==='quit-exam'){clearInterval(practice?.timer);practice=null;return render('practice')}if(a==='save-notes'){patch({notes:document.querySelector('#notes')?.value||''});toast('Carnet enregistré sur cet appareil.');return}if(a==='export'){return exportData()}if(a==='import'){return document.querySelector('#import-file')?.click()}if(a==='restore-code'){const inp=document.querySelector('#restore-code');const code=inp?.value||'';inp&&(inp.disabled=true);restoreFromCode(code).then(data=>{state={...DEFAULT,...data,account:{code:String(code).toUpperCase().trim(),sync:true}};save();toast('Carnet retrouvé et synchronisé.');render('home')}).catch(()=>{toast('Code introuvable : vérifie les lettres et les chiffres.')}).finally(()=>{inp&&(inp.disabled=false)});return}if(a==='copy-code'){const c=state.account?.code||'';if(navigator.clipboard&&c)navigator.clipboard.writeText(c).then(()=>toast('Code copié : garde-le précieusement.'));return}if(a==='toggle-sync'){if(state.account){patch({account:{...state.account,sync:!state.account.sync}});toast(state.account.sync?'Synchronisation arrêtée (local uniquement).':'Synchronisation réactivée.');render('home')}return}if(a==='suggest'){let i=document.querySelector('#coach-input');if(i){i.value=el.dataset.q;i.focus()}return}});
  document.addEventListener('change',e=>{if(e.target.id==='rate')patch({rate:Number(e.target.value)||.94});if(e.target.id==='import-file'&&e.target.files[0]){let r=new FileReader();r.onload=()=>{try{state={...DEFAULT,...JSON.parse(r.result)};save();render('memory');toast('Carnet importé.')}catch(_){toast('Fichier de carnet invalide.')}};r.readAsText(e.target.files[0])}});
  document.addEventListener('input',e=>{if(e.target.id==='notes'){state.notes=e.target.value;save();let s=document.querySelector('#note-status');if(s)s.textContent='Enregistrement automatique…'}});
  async function submitProfile(form){const fd=new FormData(form),profile={level:fd.get('level'),examDate:fd.get('examDate')||'',minutes:Number(fd.get('minutes')||15),oral:fd.get('oral'),reading:fd.get('reading'),audio:fd.get('audio'),themes:[...form.querySelectorAll('input[name="themes"]:checked')].map(x=>Number(x.value)),consented:fd.get('aiConsent')==='on'};const local=localPlan(profile);if(!state.account?.code)patch({account:{code:makeCode(),sync:true}});patch({profile,profileComplete:true,plan:local,planSource:'local',day:local.order[0]||1});render('home');if(!profile.consented)return;try{const res=await fetch('./api/personalize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profile,completed:state.completed})});if(!res.ok)throw new Error('api');const plan=await res.json();if(Array.isArray(plan.order)&&plan.order.length){patch({plan:{...local,...plan},planSource:'ai'});render('home');toast('Ton programme a été affiné par Marianne.')}}catch(_){toast('Programme local activé : il s’adapte déjà à tes réponses.')}}
  document.addEventListener('submit',e=>{if(e.target.id==='onboarding-form'){e.preventDefault();submitProfile(e.target);return}if(e.target.id==='coach-form'){e.preventDefault();let input=document.querySelector('#coach-input'),q=input?.value.trim();if(!q)return;let chat=state.chat||[{who:'ai',text:'Bonjour, je suis Marianne. Je peux reformuler une notion avec des mots simples.'}];patch({chat:[...chat,{who:'me',text:q},{who:'ai',text:coachReply(q)}]});render('coach')}});
